import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import { readFileSync, readdirSync } from 'node:fs';

// Legacy redirects (old Jekyll URLs → new) generated by scripts/migrate-content.mjs.
// Astro emits a meta-refresh + canonical HTML page for each, reproducing the
// behaviour of the old _plugins/redirect_generator.rb and the manual .html stubs.
const redirects = JSON.parse(
  readFileSync(new URL('./src/redirects.json', import.meta.url), 'utf-8'),
);

const SITE_URL = 'https://angelo-lima.fr';

// <lastmod> for article URLs in the sitemap: `lastUpdated` when set, else `date`.
// Read straight from the Markdown frontmatter (the content collection is not
// available at config time).
const postLastmod = new Map();
for (const lang of ['fr', 'en']) {
  const dir = new URL(`./src/content/posts/${lang}/`, import.meta.url);
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.md'))) {
    const fm = readFileSync(new URL(file, dir), 'utf-8').split(/^---$/m)[1] ?? '';
    const field = (name) => fm.match(new RegExp(`^${name}:\\s*"?([^"\\n]+)"?\\s*$`, 'm'))?.[1];
    const slug = field('slug');
    const date = field('lastUpdated') ?? field('date');
    if (slug && date) postLastmod.set(`${SITE_URL}/${lang}/${slug}/`, new Date(date).toISOString());
  }
}

export default defineConfig({
  site: SITE_URL,
  // All canonical URLs keep their trailing slash, exactly like the Jekyll site.
  trailingSlash: 'always',
  build: { format: 'directory' },
  redirects,
  integrations: [
    sitemap({
      // hreflang alternates are emitted per-page in <head>; the sitemap stays simple & valid.
      // Exclude 404/offline and paginated pages (robots.txt disallows /page/ to avoid duplicates).
      filter: (page) =>
        !page.includes('/404') &&
        !page.includes('/offline') &&
        !/\/page\/\d+\//.test(page),
      serialize: (item) => {
        const lastmod = postLastmod.get(decodeURI(item.url));
        return lastmod ? { ...item, lastmod } : item;
      },
    }),
  ],
  markdown: {
    gfm: true,
    smartypants: false,
    shikiConfig: {
      theme: 'github-dark',
      wrap: false,
    },
  },
});
